#!/usr/bin/env bash
# Measure rime_deployer WorkspaceUpdate performance: old (serial) vs new
# (parallel dictionary compilation), and verify the produced artifacts are
# byte-identical.
#
# Usage:
#   benchmarks/deploy/run_bench.sh --old <dir> --new <dir> \
#       [--data <dir>] [--modify-dict <name>] [--rounds N] [--out report.md] \
#       [--reuse-cold] [--fail-on-diff]
#
#   --old, --new    build dirs containing bin/rime_deployer + lib/librime.so.
#                   See build.sh to produce them.
#   --data          shared data dir; generated by gen_data.py if omitted.
#   --modify-dict   dictionary file (basename) used by the modified scenario;
#                   auto-detected from --data when omitted.
#   --rounds        number of timing runs, best kept (default 3).
#   --out           markdown report file (default ./deploy_bench_report.md).
#   --reuse-cold    reuse the last cold user dir for warm/modified; saves two
#                   full cold deploys per build (warm/modified run once).
#   --fail-on-diff  exit non-zero when cold artifacts differ between builds.
#
# The modified scenario appends to the dictionary file in --data, then restores
# it. Pass a copy of real data, not a symlink farm or your live user directory.
#
# Measures, per build:
#   cold     first deploy on an empty user dir (all dictionaries compile)
#   warm     redeploy with nothing changed (incremental, checksum only)
#   modified redeploy after touching one dictionary source file
#
# Requires the benchmark tool rime_deployer and glog-compatible logging is
# optional. The deployer writes its own log; redirect stdout/stderr to /dev/null.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

OLD=""
NEW=""
DATA=""
MODIFY_DICT=""
ROUNDS=3
OUT="deploy_bench_report.md"
REUSE_COLD=0
FAIL_ON_DIFF=0

while [[ $# -gt 0 ]]; do
  case "$1" in
    --old) OLD="$2"; shift 2 ;;
    --new) NEW="$2"; shift 2 ;;
    --data) DATA="$2"; shift 2 ;;
    --modify-dict) MODIFY_DICT="$2"; shift 2 ;;
    --rounds) ROUNDS="$2"; shift 2 ;;
    --out) OUT="$2"; shift 2 ;;
    --reuse-cold) REUSE_COLD=1; shift ;;
    --fail-on-diff) FAIL_ON_DIFF=1; shift ;;
    *) echo "unknown option: $1"; exit 1 ;;
  esac
done

[[ -n "$OLD" && -n "$NEW" ]] || { echo "error: --old and --new are required"; exit 1; }
(( ROUNDS >= 1 )) || { echo "error: --rounds must be at least 1"; exit 1; }
for d in "$OLD" "$NEW"; do
  [[ -x "$d/bin/rime_deployer" && -e "$d/lib/librime.so" ]] || {
    echo "error: $d does not look like a rime build dir (missing bin/rime_deployer or lib/librime.so)"; exit 1; }
done

WORK="$(mktemp -d /tmp/rime_deploy_bench.XXXXXX)"
trap 'rm -rf "$WORK"' EXIT

if [[ -z "$DATA" ]]; then
  DATA="$WORK/shared"
  python3 "$SCRIPT_DIR/gen_data.py" --out "$DATA" >/dev/null
fi

if [[ -z "$MODIFY_DICT" ]]; then
  for f in "$DATA"/*.dict.yaml; do
    [[ -e "$f" ]] && { MODIFY_DICT="$(basename "$f")"; break; }
  done
fi
[[ -n "$MODIFY_DICT" ]] || { echo "error: no *.dict.yaml found in $DATA"; exit 1; }
if [[ ! -f "$DATA/$MODIFY_DICT" ]]; then
  echo "error: $DATA/$MODIFY_DICT is not a regular file"; exit 1
fi
if [[ -L "$DATA/$MODIFY_DICT" ]]; then
  echo "error: $DATA/$MODIFY_DICT is a symlink; benchmark a copied data dir"; exit 1
fi

DEPLOY() { # build_dir user_dir shared_dir
  "$1/bin/rime_deployer" --build "$2" "$3" "$2/build" >/dev/null 2>&1
}

now_ns() { date +%s%N; }

# measure <label> <user_base_dir> <shared_dir> <mode> [touch_file]
#   mode = fresh  : a brand-new user dir per round (cold build each time)
#   mode = warm   : reuse the dir; requires it to be pre-deployed (nothing changes)
#   mode = modify : reuse the dir; append a unique comment line to the given
#                   source file each round so its content checksum changes and
#                   the dictionary actually recompiles
# Best (minimum) round wins.
measure() {
  local label="$1" user_base="$2" shared_dir="$3" mode="$4" touch_file="${5:-}"
  local best=-1
  for ((r = 0; r < ROUNDS; r++)); do
    local user_dir="$user_base"
    if [[ "$mode" == fresh ]]; then
      user_dir="${user_base}${r}"
      rm -rf "$user_dir"
      mkdir -p "$user_dir"
    fi
    if [[ "$mode" == modify ]]; then
      printf '\n# bench modification %d\n' "$RANDOM" >> "$shared_dir/$touch_file"
    fi
    local t0 t1 dt
    t0=$(now_ns)
    DEPLOY "$BUILD_DIR" "$user_dir" "$shared_dir"
    t1=$(now_ns)
    dt=$(( (t1 - t0) / 1000000 ))
    if (( best < 0 )) || (( dt < best )); then best=$dt; fi
  done
  eval "$label=$best"
}

run_build() { # build_dir build_name
  local build_dir="$1" build_name="$2"
  local cold_base="$WORK/${build_name}_cold"
  local warm_dir="$WORK/${build_name}_warm"
  local mod_dir="$WORK/${build_name}_mod"
  if (( REUSE_COLD )); then
    warm_dir="${cold_base}$((ROUNDS - 1))"
    mod_dir="$warm_dir"
  fi
  local mod_dict="$DATA/$MODIFY_DICT"

  rm -rf "$cold_base"
  if (( ! REUSE_COLD )); then
    rm -rf "$warm_dir" "$mod_dir"
  fi

  BUILD_DIR="$build_dir" measure cold_ms "$cold_base" "$DATA" fresh
  cp -r "${cold_base}0/build" "$WORK/${build_name}_cold_artifacts"
  # warm: pre-deploy once unless reusing the last cold dir, then measure
  if (( ! REUSE_COLD )); then
    DEPLOY "$build_dir" "$warm_dir" "$DATA"
  fi
  BUILD_DIR="$build_dir" measure warm_ms "$warm_dir" "$DATA" warm
  # modified: pre-deploy once unless reusing, then change one dict and redeploy
  if (( ! REUSE_COLD )); then
    DEPLOY "$build_dir" "$mod_dir" "$DATA"
  fi
  cp "$mod_dict" "$mod_dict.bak"
  BUILD_DIR="$build_dir" measure mod_ms "$mod_dir" "$DATA" modify "$MODIFY_DICT"
  mv "$mod_dict.bak" "$mod_dict"

  echo "$build_name $cold_ms $warm_ms $mod_ms"
}

OLD_RES=$(run_build "$OLD" old)
NEW_RES=$(run_build "$NEW" new)

OLD_COLD=$(echo "$OLD_RES" | awk '{print $2}')
OLD_WARM=$(echo "$OLD_RES" | awk '{print $3}')
OLD_MOD=$(echo "$OLD_RES" | awk '{print $4}')
NEW_COLD=$(echo "$NEW_RES" | awk '{print $2}')
NEW_WARM=$(echo "$NEW_RES" | awk '{print $3}')
NEW_MOD=$(echo "$NEW_RES" | awk '{print $4}')

calc_speedup() { # old_ms new_ms -> prints x.xx
  awk -v o="$1" -v n="$2" 'BEGIN { printf "%.2f", o / n }'
}

# ---- artifact comparison (cold outputs, first round of each build) --------
ARTIFACTS_IDENTICAL=0
if diff -r "$WORK/old_cold_artifacts" "$WORK/new_cold_artifacts" \
    >/dev/null 2>&1; then
  ARTIFACTS_IDENTICAL=1
fi

{
  echo "# Rime deployment benchmark"
  echo
  if (( REUSE_COLD )); then
    echo "Cold: best of $ROUNDS runs. Warm and modified: single run from the last cold user dir."
  else
    echo "Best of $ROUNDS runs. Old: serial. New: parallel dictionary compilation."
  fi
  echo "Shared data: $DATA"
  echo
  echo "| scenario | old (ms) | new (ms) | speedup |"
  echo "|---|---|---|---|"
  echo "| cold (full rebuild) | $OLD_COLD | $NEW_COLD | $(calc_speedup "$OLD_COLD" "$NEW_COLD") |"
  echo "| warm (nothing changed) | $OLD_WARM | $NEW_WARM | $(calc_speedup "$OLD_WARM" "$NEW_WARM") |"
  echo "| one dict modified | $OLD_MOD | $NEW_MOD | $(calc_speedup "$OLD_MOD" "$NEW_MOD") |"
  echo
  echo "## Artifact consistency (cold build outputs)"
  echo
  if (( ARTIFACTS_IDENTICAL )); then
    echo "All deployed artifacts are byte-identical between old and new."
  else
    echo "Artifacts DIFFER:"
    echo
    echo '```'
    diff -r "$WORK/old_cold_artifacts" "$WORK/new_cold_artifacts" | head -40 || true
    echo '```'
  fi
} | tee "$OUT"

if (( FAIL_ON_DIFF )) && (( ! ARTIFACTS_IDENTICAL )); then
  echo "error: deployed artifacts differ between old and new." >&2
  exit 1
fi
